        "short",
        "full"
      ],
      "default": "off"
    },
    "guideKeywords": {
      "type": "string",
      "title": "full のきっかけの語",
      "description": "guide が full のとき、入力にこの語（カンマ区切り、大文字小文字は区別しない）のどれかが含まれると、ツールの使い分けの要点を足す（5 ターンに 1 回まで）",
      "default": "ボード,whiteboard"
    }
  }
}

